contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry driving c.play with an arbitrary payment amount
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract can send `amount` wei
        require(address(this).balance >= amount);

        // observe before state
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        uint balance_before = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        address bank_after = c.bank(); if (__ESBMC_reverted()) return;
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint balance_after = address(c).balance;

        // constants (mirror of C)
        uint TICKET_AMOUNT = 10;

        // General rule:
        // 1) play never changes the bank address (bank_after == bank_before) whether it reverts or not;
        // 2) If the call reverted, then pot and contract balance are unchanged;
        // 3) If the call succeeded, then amount must have been exactly TICKET_AMOUNT, and pot_after is either pot_before + TICKET_AMOUNT or 0.
        assert(
            // bank unchanged
            bank_after == bank_before
            && (
                // reverted: pot and balance unchanged
                (reverted && pot_after == pot_before && balance_after == balance_before)
                ||
                // succeeded: must have paid exact ticket and pot is either increased by ticket or reset to 0
                (!reverted && amount == TICKET_AMOUNT && (pot_after == pot_before + TICKET_AMOUNT || pot_after == 0))
            )
        );
    }

    // accept incoming Ether transfers from C when it pays out
    receive() external payable {}
}

