// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address bank_before;
        try c.bank() returns (address __r) { bank_before = __r; } catch { return; }
        uint256 pot_before;
        try c.pot() returns (uint256 __r) { pot_before = __r; } catch { return; }
        uint balance_before = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address bank_after;
        try c.bank() returns (address __r) { bank_after = __r; } catch { return; }
        uint256 pot_after;
        try c.pot() returns (uint256 __r) { pot_after = __r; } catch { return; }
        uint balance_after = address(c).balance;
        uint TICKET_AMOUNT = 10;
        assertTrue(bank_after == bank_before
            && (
                // reverted: pot and balance unchanged
                (reverted && pot_after == pot_before && balance_after == balance_before)
                ||
                // succeeded: must have paid exact ticket and pot is either increased by ticket or reset to 0
                (!reverted && amount == TICKET_AMOUNT && (pot_after == pot_before + TICKET_AMOUNT || pot_after == 0))
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
